sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        gs.info('PRM Email Notification - Starting Business Rule execution.');

        // Get the sys_id of the user creating the record
        var creatorSysID = current.getValue('opened_by');
        if (!creatorSysID) {
            gs.error('PRM Email Notification - No creator (opened_by) found for the record.');
            return;
        }
        gs.info('PRM Email Notification - Creator sys_id: ' + creatorSysID);

        // Fetch the groups the creator belongs to
        var creatorGroups = getUserGroups(creatorSysID);
        if (!creatorGroups || creatorGroups.length === 0) {
            gs.info('PRM Email Notification - No groups found for the user creating the record.');
            return;
        }
        gs.info('PRM Email Notification - Creator Groups: ' + JSON.stringify(creatorGroups));

        // Extract the instance identifier from the group names
        var instanceIdentifier = extractInstanceIdentifier(creatorGroups);
        if (!instanceIdentifier) {
            gs.info('PRM Email Notification - No instance identifier found in the user groups.');
            return;
        }
        gs.info('PRM Email Notification - Instance Identifier: ' + instanceIdentifier);

        // Fetch the country code and product team
        var refRec = current.receiving_country_territory.getRefRecord();
        var countryCode = refRec ? refRec.getValue('iso3166_2') : null;
        var productTeamReq = current.getValue('product_team');
        var productTeam = current.getValue('receiving_product_team');

        if (!countryCode || !productTeam) {
            gs.error('PRM Email Notification - Country code or product team is missing.');
            return;
        }
        gs.info('PRM Email Notification - Country Code: ' + countryCode + ', Product Team: ' + productTeam + ', Product Team Req: ' + productTeamReq);

        // Determine approver roles based on creator's groups and state
        var approverRoles = determineApproverRoles(creatorGroups, current.getValue('state'), instanceIdentifier);
        gs.info('PRM Email Notification - Approver Roles determined: ' + approverRoles.join(','));

        // State-specific logic
        var filteredEmails = [];
        var state = current.getValue('state');
        gs.info('PRM Email Notification - Current State: ' + state);

        if (state === '6') {
            // State 6 logic
            gs.info('PRM Email Notification - Processing logic for state 6...');
            var locationGroups = creatorGroups.filter(group => group.name.match(/^Infodir-iQube-[A-Za-z0-9-]+-PRM-HBAP-[A-Z]{2}$/));
            var productGroups = creatorGroups.filter(group => group.name.match(new RegExp(`^Infodir-iQube-[A-Za-z0-9-]+-PRM-${productTeamReq}$`)));

            gs.info('PRM Email Notification - Filtered Location Groups for State 6: ' + JSON.stringify(locationGroups));
            gs.info('PRM Email Notification - Filtered Product Groups for State 6: ' + JSON.stringify(productGroups));

            var usersToNotify = findUsersInGroups(locationGroups, productGroups);
            filteredEmails = usersToNotify.map(userSysID => getUserEmail(userSysID)).filter(email => email);
        } else if (state === '7') {
            // State 7 logic
            gs.info('PRM Email Notification - Processing logic for state 7...');
            locationGroups = creatorGroups.filter(group => group.name.match(/^Infodir-iQube-[A-Za-z0-9-]+-PRM-HBAP-[A-Z]{2}$/));
            productGroups = creatorGroups.filter(group => group.name.match(new RegExp(`^Infodir-iQube-[A-Za-z0-9-]+-PRM-${productTeamReq}$`)));

            gs.info('PRM Email Notification - Filtered Location Groups for State 7: ' + JSON.stringify(locationGroups));
            gs.info('PRM Email Notification - Filtered Product Groups for State 7: ' + JSON.stringify(productGroups));

            usersToNotify = findUsersInGroups(locationGroups, productGroups);
            filteredEmails = usersToNotify.map(userSysID => getUserEmail(userSysID)).filter(email => email);
        } else if (state === '8') {
            // State 8 logic
            gs.info('PRM Email Notification - Processing logic for state 8...');
            var state8Emails = getEmailsFromGroups([
                `Infodir-iQube-${instanceIdentifier}-PRM-SglApprvr`,
                `Infodir-iQube-${instanceIdentifier}-PRM-ReqrProc`
            ]);

            var group1Emails = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-HBAP-${countryCode}`]);
            var group2Emails = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-${productTeam}`]);

            var additionalEmails = group1Emails.filter(email => group2Emails.includes(email));
            filteredEmails = state8Emails.filter(email => additionalEmails.includes(email));
        } else if (state === '9') {
            // State 9 logic
            gs.info('PRM Email Notification - Processing logic for state 9...');
            var state9Emails = getEmailsFromGroups([
                `Infodir-iQube-${instanceIdentifier}-PRM-Apprvr`
            ]);

            var group1EmailsState9 = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-HBAP-${countryCode}`]);
            var group2EmailsState9 = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-${productTeam}`]);

            var additionalEmailsState9 = group1EmailsState9.filter(email => group2EmailsState9.includes(email));
            filteredEmails = state9Emails.filter(email => additionalEmailsState9.includes(email));
        }

        // Filter emails based on approver roles
        filteredEmails = filterEmailsByRoles(filteredEmails, approverRoles);

        // Remove duplicates from the email list
        filteredEmails = [...new Set(filteredEmails)];
        gs.info('PRM Email Notification - Final filtered email list: ' + filteredEmails.join(','));

        // Update the field with the filtered email list
        current.setValue('prm_user_email_lst', filteredEmails.join(','));
        current.update();
        gs.info('PRM Email Notification - Updated prm_user_email_lst field with filtered emails: ' + filteredEmails.join(','));
    } catch (err) {
        gs.error('PRM Email Notification - Error in merged Business Rule: ' + err.message + '\n' + err.stack);
    }

    // ========= Helper Functions =========

    function getUserGroups(userSysID) {
        var groups = [];
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('user', userSysID);
        gr.query();
        while (gr.next()) {
            groups.push({
                sys_id: gr.group.sys_id.toString(),
                name: gr.group.name.toString()
            });
        }
        return groups;
    }

    function extractInstanceIdentifier(groups) {
        for (var i = 0; i < groups.length; i++) {
            var match = groups[i].name.match(/^Infodir-iQube-([A-Za-z0-9-]+)-PRM/);
            if (match && match[1]) {
                return match[1];
            }
        }
        return null;
    }

    function determineApproverRoles(creatorGroups, state, instanceIdentifier) {
        var approverRoles = [];
        var creatorRoleNames = creatorGroups.map(group => group.name);

        creatorRoleNames.forEach(role => {
            if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ReqrNAUTH-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-L1Apprvr`);
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
                if (state === '7') {
                    approverRoles = [`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L2Apprvr`];
                }
            } else if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
            } else if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-L1Apprvr`);
            }
        });
        return approverRoles;
    }

    function getEmailsFromGroups(groupNames) {
        var emails = [];
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('group.name', 'IN', groupNames.join(','));
        gr.query();
        while (gr.next()) {
            var userEmail = gr.user.email.toString();
            if (userEmail) {
                emails.push(userEmail);
            }
        }
        return emails;
    }

    function findUsersInGroups(locationGroups, productGroups) {
        var usersInAllGroups = [];
        var locationGroupIDs = locationGroups.map(group => group.sys_id);
        var productGroupIDs = productGroups.map(group => group.sys_id);

        var locationUsers = getUsersInGroups(locationGroupIDs);
        var productUsers = getUsersInGroups(productGroupIDs);

        usersInAllGroups = locationUsers.filter(user => productUsers.includes(user));
        return usersInAllGroups;

        function getUsersInGroups(groupIDs) {
            var users = [];
            if (groupIDs.length === 0) {
                return users;
            }

            var gr = new GlideRecord('sys_user_grmember');
            gr.addQuery('group', 'IN', groupIDs.join(','));
            gr.query();
            while (gr.next()) {
                var userSysID = gr.user.sys_id.toString();
                if (!users.includes(userSysID)) {
                    users.push(userSysID);
                }
            }
            return users;
        }
    }

    function getUserEmail(userSysID) {
        var gr = new GlideRecord('sys_user');
        gr.addQuery('sys_id', userSysID);
        gr.query();
        if (gr.next()) {
            return gr.email.toString();
        }
        return null;
    }

    function filterEmailsByRoles(emailArray, approverRoles) {
        var filteredEmails = [];
        var gr = new GlideRecord('sys_user');
        gr.addQuery('email', 'IN', emailArray.join(','));
        gr.query();
        while (gr.next()) {
            var userGroups = getUserGroups(gr.sys_id.toString());
            var userRoleNames = userGroups.map(group => group.name);
            if (approverRoles.some(role => userRoleNames.includes(role))) {
                filteredEmails.push(gr.email.toString());
            }
        }
        return filteredEmails;
    }
})(current, previous);
